//! Markdown pages generated from code, for the documentation book.

use std::fmt::Write as _;

/// A generated Markdown page, written top to bottom.
pub struct Page {
    text: String,
    /// Whether the page ends with a list item, which the next one continues.
    in_list: bool,
}

impl Page {
    /// Starts a page: a comment telling readers not to edit it and naming
    /// `source`, then its title and the hand-written `intro`.
    pub fn new(source: &str, title: &str, intro: &str) -> Self {
        Self {
            text: format!(
                "<!-- Generated by `just generate` from {source}. Do not edit it by hand. -->\n\n# {title}\n\n{intro}\n"
            ),
            in_list: false,
        }
    }

    /// Adds a heading of `level` (2 for `##`).
    pub fn heading(&mut self, level: usize, text: &str) {
        let _ = write!(self.text, "\n{} {text}\n", "#".repeat(level));
        self.in_list = false;
    }

    /// Adds doc-comment or help `text` as paragraphs, see [`Self::prose`].
    pub fn paragraphs(&mut self, text: &str) {
        let _ = write!(self.text, "\n{}\n", Self::prose(text));
        self.in_list = false;
    }

    /// Adds `text` verbatim in a `text` code block.
    pub fn code(&mut self, text: &str) {
        let _ = write!(self.text, "\n```text\n{}\n```\n", text.trim_end());
        self.in_list = false;
    }

    /// Adds a list item nested `depth` levels deep, whose Markdown `text`
    /// may have several paragraphs. Items added one after another form one
    /// list.
    pub fn item(&mut self, depth: usize, text: &str) {
        if !self.in_list {
            self.text.push('\n');
        }
        let indent = "  ".repeat(depth);
        let _ = write!(self.text, "{indent}- ");
        for (index, line) in text.lines().enumerate() {
            if index > 0 && !line.is_empty() {
                let _ = write!(self.text, "{indent}  ");
            }
            let _ = writeln!(self.text, "{line}");
        }
        self.in_list = true;
    }

    /// The finished page.
    pub fn finish(self) -> String {
        self.text
    }

    /// Turns doc-comment or help text into Markdown: lines of a paragraph
    /// are joined, except list items, and a `<` outside code spans is
    /// escaped so it doesn't open an HTML tag.
    ///
    /// ```text
    /// "Becomes `<host>.ts.net`, see\n<host>." -> "Becomes `<host>.ts.net`, see \<host>."
    /// ```
    pub fn prose(text: &str) -> String {
        let mut joined = String::new();
        for line in text.trim().lines().map(str::trim) {
            if !joined.is_empty() && !joined.ends_with('\n') {
                joined.push(if line.is_empty() || line.starts_with("- ") {
                    '\n'
                } else {
                    ' '
                });
            }
            if line.is_empty() {
                joined.push('\n');
            }
            joined.push_str(line);
        }
        joined
            .split('`')
            .enumerate()
            .map(|(index, part)| {
                if index % 2 == 0 {
                    part.replace('<', "\\<")
                } else {
                    part.to_owned()
                }
            })
            .collect::<Vec<_>>()
            .join("`")
    }
}
